1	import { chromium } from "playwright";
2	import type { Page, BrowserContext } from "playwright";
3	import {
4	  syncScrapedPostsToHistory,
5	  expandBuffLyUrlsInText,
6	  findBuffLyUrls,
7	} from "./historyStore";
8	
9	// ============================================================================
10	// Types and Interfaces
11	// ============================================================================
12	
13	interface LinkedInPostMetrics {
14	  reactions: number | null;
15	  comments: number | null;
16	  impressions: number | null;
17	  reach: number | null;
18	  engagementRate: string | null;
19	}
20	
21	interface LinkedInPost {
22	  platform: "LinkedIn";
23	  postText: string;
24	  postedDateTime: string;
25	  metrics: LinkedInPostMetrics;
26	}
27	
28	type ChannelType = "LinkedIn" | "BlueSky" | "Mastodon";
29	
30	// Channel IDs for Buffer URL-based filtering
31	const CHANNEL_IDS: Record<ChannelType, string> = {
32	  LinkedIn: "51a55227ead9b8a169000025",
33	  BlueSky: "",
34	  Mastodon: "",
35	};
36	
37	// Cutoff date: 6 weeks ago from today
38	const CUTOFF_DATE = new Date(Date.now() - 6 * 7 * 24 * 60 * 60 * 1000);
39	
40	// ============================================================================
41	// Date Utilities
42	// ============================================================================
43	
44	/**
45	 * Format a Date object as "YYYY-MM-DD HH:mm:ss"
46	 */
47	function formatDateTime(date: Date): string {
48	  const year = date.getFullYear();
49	  const month = String(date.getMonth() + 1).padStart(2, "0");
50	  const day = String(date.getDate()).padStart(2, "0");
51	  const hours = String(date.getHours()).padStart(2, "0");
52	  const minutes = String(date.getMinutes()).padStart(2, "0");
53	  const seconds = String(date.getSeconds()).padStart(2, "0");
54	  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
55	}
56	
57	/**
58	 * Parse Buffer's date format: "Saturday, January 17" + "10:29 AM"
59	 */
60	function parseBufferDate(dayPart: string, timePart: string): Date | null {
61	  if (!dayPart) return null;
62	
63	  const now = new Date();
64	  const currentYear = now.getFullYear();
65	
66	  const cleanDay = dayPart.trim();
67	  const cleanTime = timePart?.trim() || "12:00 PM";
68	
69	  // Handle "X days ago" format
70	  const daysAgoMatch = cleanDay.match(/(\d+)\s*days?\s*ago/i);
71	  if (daysAgoMatch) {
72	    const daysAgo = parseInt(daysAgoMatch[1], 10);
73	    const date = new Date(now);
74	    date.setDate(date.getDate() - daysAgo);
75	    return date;
76	  }
77	
78	  // Parse "Saturday, January 17" format
79	  const withoutDayName = cleanDay.replace(/^[A-Za-z]+,\s*/, "");
80	
81	  // Try with current year first
82	  const dateWithYear = `${withoutDayName}, ${currentYear}`;
83	  let date = new Date(`${dateWithYear} ${cleanTime}`);
84	
85	  if (!isNaN(date.getTime())) {
86	    // If in the future, use previous year
87	    if (date > now) {
88	      date = new Date(`${withoutDayName}, ${currentYear - 1} ${cleanTime}`);
89	    }
90	    return date;
91	  }
92	
93	  // Fallback
94	  date = new Date(`${cleanDay} ${cleanTime}`);
95	  if (!isNaN(date.getTime())) return date;
96	
97	  return null;
98	}
99	
100	/**
101	 * Check if a date is after the cutoff date
102	 */
103	function isAfterCutoff(date: Date): boolean {
104	  return date >= CUTOFF_DATE;
105	}
106	
107	// ============================================================================
108	// Metric Extraction Utilities
109	// ============================================================================
110	
111	function parseMetricValue(text: string | null): number | null {
112	  if (!text || text === "-" || text === "--" || text.trim() === "") return null;
113	
114	  const cleaned = text.trim().replace(/,/g, "");
115	
116	  const suffixMatch = cleaned.match(/^([\d.]+)\s*([KkMm])?$/);
117	  if (suffixMatch) {
118	    let value = parseFloat(suffixMatch[1]);
119	    if (isNaN(value)) return null;
120	
121	    const suffix = suffixMatch[2]?.toUpperCase();
122	    if (suffix === "K") value *= 1000;
123	    if (suffix === "M") value *= 1000000;
124	
125	    return Math.round(value);
126	  }
127	
128	  const num = parseFloat(cleaned);
129	  return isNaN(num) ? null : Math.round(num);
130	}
