132	// ============================================================================
133	// Buffer Scraper Class
134	// ============================================================================
135	
136	class BufferScraper {
137	  private context: BrowserContext | null = null;
138	  private page: Page | null = null;
139	
140	  async init(): Promise<void> {
141	    const userDataDir = process.env.HOME + "/.buffer-playwright-session";
142	
143	    this.context = await chromium.launchPersistentContext(userDataDir, {
144	      headless: false,
145	      viewport: { width: 1400, height: 900 },
146	    });
147	
148	    this.page = this.context.pages()[0] || (await this.context.newPage());
149	  }
150	
151	  async navigateToChannel(channel: ChannelType): Promise<void> {
152	    if (!this.page) throw new Error("Browser not initialized");
153	
154	    const channelId = CHANNEL_IDS[channel];
155	    const url = channelId
156	      ? `https://publish.buffer.com/all-channels?channels[]=${channelId}&tab=sent`
157	      : "https://publish.buffer.com/all-channels?tab=sent";
158	
159	    console.log(`Navigating to: ${url}`);
160	    await this.page.goto(url, { waitUntil: "domcontentloaded" });
161	    await this.page.waitForTimeout(3000);
162	
163	    // Check if we need to log in
164	    const loginVisible = await this.page
165	      .locator('button:has-text("Log in"), a:has-text("Log in")')
166	      .first()
167	      .isVisible()
168	      .catch(() => false);
169	
170	    if (loginVisible) {
171	      console.log("\n========================================");
172	      console.log("Please log in to Buffer in the browser window.");
173	      console.log("Once logged in, the script will continue automatically.");
174	      console.log("========================================\n");
175	
176	      await this.page.waitForURL("**/all-channels**", { timeout: 300000 });
177	      await this.page.waitForTimeout(3000);
178	    }
179	  }
180	
181	  /**
182	   * Load more posts via infinite scroll until we reach the cutoff date
183	   */
184	  async loadPostsUntilCutoff(): Promise<void> {
185	    if (!this.page) return;
186	
187	    console.log(
188	      `\nLoading posts back to ${CUTOFF_DATE.toISOString().split("T")[0]} via infinite scroll...`,
189	    );
190	
191	    let scrollCount = 0;
192	    const maxScrolls = 200; // Safety limit
193	    let noNewContentCount = 0;
194	
195	    while (scrollCount < maxScrolls) {
196	      scrollCount++;
197	
198	      // Check if we've reached the cutoff date by looking at visible dates
199	      const oldestDateVisible = await this.page.evaluate(() => {
200	        const datePattern =
201	          /(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday),\s+([A-Z][a-z]+\s+\d{1,2})/g;
202	        const bodyText = document.body.innerText;
203	        const matches: string[] = [];
204	        let match;
205	        while ((match = datePattern.exec(bodyText)) !== null) {
206	          matches.push(match[0]);
207	        }
208	        if (matches.length > 0) {
209	          return matches[matches.length - 1]; // Last (oldest) date
210	        }
211	        return null;
212	      });
213	
214	      if (oldestDateVisible) {
215	        const oldestDate = parseBufferDate(oldestDateVisible, "12:00 PM");
216	        if (oldestDate && oldestDate < CUTOFF_DATE) {
217	          console.log(
218	            `\nReached cutoff date. Oldest visible: ${oldestDateVisible}`,
219	          );
220	          break;
221	        }
222	        if (scrollCount % 10 === 0) {
223	          console.log(
224	            `Scroll ${scrollCount}: oldest date = ${oldestDateVisible}`,
225	          );
226	        }
227	      }
228	
229	      // Get current scroll height
230	      const previousHeight = await this.page.evaluate(
231	        () => document.body.scrollHeight,
232	      );
233	
234	      // Scroll to bottom of page
235	      await this.page.evaluate(() => {
236	        window.scrollTo(0, document.body.scrollHeight);
237	      });
238	
239	      // Wait for content to load
240	      await this.page.waitForTimeout(1500);
241	
242	      // Check if new content loaded
243	      const newHeight = await this.page.evaluate(
244	        () => document.body.scrollHeight,
245	      );
246	
247	      if (newHeight === previousHeight) {
248	        // Try scrolling within scrollable containers (Buffer might use a scrollable div)
249	        const scrolledContainer = await this.page.evaluate(() => {
250	          const containers = document.querySelectorAll("*");
251	          for (let i = 0; i < containers.length; i++) {
252	            const el = containers[i];
253	            if (el instanceof HTMLElement) {
254	              const style = window.getComputedStyle(el);
255	              const isScrollable =
256	                (style.overflowY === "auto" || style.overflowY === "scroll") &&
257	                el.scrollHeight > el.clientHeight;
258	              if (isScrollable && el.scrollHeight > 500) {
259	                const prevScroll = el.scrollTop;
260	                el.scrollTop = el.scrollHeight;
261	                return el.scrollTop !== prevScroll;
262	              }
263	            }
264	          }
265	          return false;
266	        });
267	
268	        if (!scrolledContainer) {
269	          noNewContentCount++;
270	          if (noNewContentCount >= 3) {
271	            console.log(
272	              "\nNo more content to load (scroll stopped producing new content)",
273	            );
274	            break;
275	          }
276	        } else {
277	          noNewContentCount = 0;
278	          await this.page.waitForTimeout(1500);
279	        }
280	      } else {
281	        noNewContentCount = 0;
282	      }
283	    }
284	
285	    console.log(`Finished loading after ${scrollCount} scrolls`);
286	  }
287	
288	  /**
289	   * Extract all LinkedIn posts from current view
290	   */
291	  async extractLinkedInPosts(): Promise<LinkedInPost[]> {
292	    if (!this.page) throw new Error("Browser not initialized");
293	
294	    const posts: LinkedInPost[] = [];
295	
296	    console.log("\nAnalyzing page structure...");
297	
298	    const postContainers = await this.page.evaluate(() => {
299	      const results: Array<{
300	        text: string;
301	        dateHeader: string;
302	        time: string;
303	        reactions: string;
304	        comments: string;
305	        impressions: string;
306	        reach: string;
307	        engRate: string;
308	      }> = [];
309	
310	      // Find all metrics containers via aria-label
311	      const metricsRegions = document.querySelectorAll(
312	        '[aria-label="Metrics list"]',
313	      );
314	
315	      // For each metrics region, extract metrics via DOM structure and
316	      // walk up to find the post card container
317	      const postParents = new Set<Element>();
318	      const metricsMap = new Map<Element, Record<string, string>>();
319	
320	      metricsRegions.forEach((region) => {
321	        // Extract metrics directly from DOM: each metric is a wrapper div
322	        // with a label span (.publish_label_) and a value span (.publish_metric_)
323	        const metrics: Record<string, string> = {};
324	        region
325	          .querySelectorAll('[class*="publish_wrapper_"]')
326	          .forEach((wrapper) => {
327	            const labelEl = wrapper.querySelector(
328	              '[class*="publish_label_"] span',
329	            );
330	            const valueEl = wrapper.querySelector(
331	              ':scope > [class*="publish_metric_"]',
332	            );
333	            if (labelEl && valueEl) {
334	              const label = labelEl.textContent?.trim() || "";
335	              const value = valueEl.textContent?.trim() || "";
336	              if (label) metrics[label] = value;
337	            }
338	          });
339	
340	        // Only process LinkedIn posts (have Reactions + Impressions)
341	        if (!metrics["Reactions"] && !metrics["Impressions"]) return;
342	
343	        // Walk up to find the post card container
344	        let parent = region.parentElement;
345	        for (let i = 0; i < 10 && parent; i++) {
346	          if (
347	            parent.textContent?.includes("View Post") &&
348	            parent.querySelector("p, [class*='text'], [class*='content']")
349	          ) {
350	            if (!postParents.has(parent)) {
351	              postParents.add(parent);
352	              metricsMap.set(parent, metrics);
353	            }
354	            break;
355	          }
356	          parent = parent.parentElement;
357	        }
358	      });
359	
360	      // Find all date headers
361	      const dateHeaderPattern =
362	        /(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday),\s+([A-Z][a-z]+\s+\d{1,2})/;
363	      const allDateHeaders: Array<{ date: string; top: number }> = [];
364	
365	      document.querySelectorAll("*").forEach((el) => {
366	        const text = el.textContent?.trim() || "";
367	        if (text.length < 50 && dateHeaderPattern.test(text)) {
368	          const match = text.match(dateHeaderPattern);
369	          if (match) {
370	            const rect = el.getBoundingClientRect();
371	            allDateHeaders.push({
372	              date: match[0],
373	              top: rect.top + window.scrollY,
374	            });
375	          }
376	        }
377	      });
378	
379	      postParents.forEach((container) => {
380	        const containerRect = container.getBoundingClientRect();
