33	function parseBufferDate(dayPart, timePart) {
34	  if (!dayPart) return null;
35	
36	  const now = new Date();
37	  const currentYear = now.getFullYear();
38	  const cleanDay = dayPart.trim();
39	  const cleanTime = timePart?.trim() || "12:00 PM";
40	
41	  // Handle "X days ago" format
42	  const daysAgoMatch = cleanDay.match(/(\d+)\s*days?\s*ago/i);
43	  if (daysAgoMatch) {
44	    const daysAgo = parseInt(daysAgoMatch[1], 10);
45	    const date = new Date(now);
46	    date.setDate(date.getDate() - daysAgo);
47	    return date;
48	  }
49	
50	  // Parse "Saturday, January 17" format
51	  // Extract the day name for validation (e.g. "Saturday")
52	  const dayNameMatch = cleanDay.match(/^([A-Za-z]+),\s*/);
53	  const expectedDayName = dayNameMatch ? dayNameMatch[1] : null;
54	  const withoutDayName = cleanDay.replace(/^[A-Za-z]+,\s*/, "");
55	  const dayNames = [
56	    "Sunday",
57	    "Monday",
58	    "Tuesday",
59	    "Wednesday",
60	    "Thursday",
61	    "Friday",
62	    "Saturday",
63	  ];
64	
65	  const dateWithYear = `${withoutDayName}, ${currentYear}`;
66	  let date = new Date(`${dateWithYear} ${cleanTime}`);
67	
68	  if (!isNaN(date.getTime())) {
69	    if (date > now) {
70	      date = new Date(`${withoutDayName}, ${currentYear - 1} ${cleanTime}`);
71	    } else if (expectedDayName) {
72	      // Validate day-of-week: if "Saturday, January 17" doesn't land on
73	      // a Saturday in the guessed year, try the previous year
74	      const actualDayName = dayNames[date.getDay()];
75	      if (actualDayName !== expectedDayName) {
76	        const prevYearDate = new Date(
77	          `${withoutDayName}, ${currentYear - 1} ${cleanTime}`,
78	        );
79	        if (
80	          !isNaN(prevYearDate.getTime()) &&
81	          dayNames[prevYearDate.getDay()] === expectedDayName
82	        ) {
83	          date = prevYearDate;
84	        }
85	      }
86	    }
87	    return date;
88	  }
89	
90	  date = new Date(`${cleanDay} ${cleanTime}`);
91	  if (!isNaN(date.getTime())) return date;
92	  return null;
93	}
