95	function parseMetricValue(text) {
96	  if (!text || text === "-" || text === "--" || text.trim() === "") return null;
97	  const cleaned = text.trim().replace(/,/g, "");
98	  const suffixMatch = cleaned.match(/^([\d.]+)\s*([KkMm])?$/);
99	  if (suffixMatch) {
100	    let value = parseFloat(suffixMatch[1]);
101	    if (isNaN(value)) return null;
102	    const suffix = suffixMatch[2]?.toUpperCase();
103	    if (suffix === "K") value *= 1000;
104	    if (suffix === "M") value *= 1000000;
105	    return Math.round(value);
106	  }
107	  const num = parseFloat(cleaned);
108	  return isNaN(num) ? null : Math.round(num);
109	}
