281	function findHistoryIndexByText(posts, scrapedText, platform) {
282	  const needle = scrapedText.substring(0, 60).toLowerCase();
283	
284	  // Pass 1: match against the platform's own field
285	  for (let i = 0; i < posts.length; i++) {
286	    const post = posts[i];
287	    const content = post[platform];
288	    if (!content) continue;
289	
290	    if (platform === "mastodon" && Array.isArray(content)) {
291	      // Match against first thread part
292	      if (content[0] && content[0].substring(0, 60).toLowerCase() === needle) {
293	        return i;
294	      }
295	    } else if (typeof content === "string") {
296	      if (content.substring(0, 60).toLowerCase() === needle) {
297	        return i;
298	      }
299	    }
300	  }
301	
302	  // Pass 2: fallback — match against linkedin text
303	  for (let i = 0; i < posts.length; i++) {
304	    const content = posts[i].linkedin;
305	    if (
306	      typeof content === "string" &&
307	      content.substring(0, 60).toLowerCase() === needle
308	    ) {
309	      return i;
310	    }
311	  }
312	
313	  return -1;
