499	      if (scrollCount % 10 === 0) {
500	        console.log(
501	          `Scroll ${scrollCount}: oldest date = ${oldestDateVisible}`,
502	        );
503	      }
504	    }
505	
506	    const previousHeight = await page.evaluate(
507	      () => document.body.scrollHeight,
508	    );
509	    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
510	    await page.waitForTimeout(1500);
511	    const newHeight = await page.evaluate(() => document.body.scrollHeight);
512	
513	    if (newHeight === previousHeight) {
514	      const scrolledContainer = await page.evaluate(() => {
515	        const containers = document.querySelectorAll("*");
516	        for (let i = 0; i < containers.length; i++) {
517	          const el = containers[i];
518	          if (el instanceof HTMLElement) {
519	            const style = window.getComputedStyle(el);
520	            const isScrollable =
521	              (style.overflowY === "auto" || style.overflowY === "scroll") &&
522	              el.scrollHeight > el.clientHeight;
523	            if (isScrollable && el.scrollHeight > 500) {
524	              const prevScroll = el.scrollTop;
525	              el.scrollTop = el.scrollHeight;
526	              return el.scrollTop !== prevScroll;
527	            }
528	          }
529	        }
530	        return false;
531	      });
532	
533	      if (!scrolledContainer) {
534	        noNewContentCount++;
535	        if (noNewContentCount >= 3) {
536	          console.log("\nNo more content to load");
537	          break;
538	        }
539	      } else {
540	        noNewContentCount = 0;
541	        await page.waitForTimeout(1500);
542	      }
543	    } else {
544	      noNewContentCount = 0;
545	    }
546	  }
547	
548	  console.log(`Finished loading after ${scrollCount} scrolls`);
549	}
