552	// Post extraction — uses string-based evaluate to avoid __name issues
553	// ============================================================================
554	
555	/**
556	 * Extract posts and metrics from the current page.
557	 * metricNames: array of metric label strings to look for, e.g. ["Reactions", "Comments"]
558	 * filterOut: array of metric labels that should NOT be present (to distinguish platforms)
559	 */
560	async function extractPosts(page, metricNames, filterOut = []) {
561	  // Use a string template for page.evaluate to completely avoid any
562	  // esbuild/tsx transformation of the function body.
563	  const metricNamesJSON = JSON.stringify(metricNames);
564	  const filterOutJSON = JSON.stringify(filterOut);
565	
566	  const postContainers = await page.evaluate(`(() => {
567	    const metricNames = ${metricNamesJSON};
568	    const filterOut = ${filterOutJSON};
569	    const results = [];
570	
571	    // Find all metrics containers via aria-label
572	    const metricsRegions = document.querySelectorAll('[aria-label="Metrics list"]');
573	    const postParents = new Set();
574	    const metricsMap = new Map();
575	
576	    metricsRegions.forEach(function(region) {
577	      // Extract metrics from DOM structure
578	      var metrics = {};
579	      var wrappers = region.querySelectorAll('[class*="publish_wrapper_"]');
580	      wrappers.forEach(function(wrapper) {
581	        var labelEl = wrapper.querySelector('[class*="publish_label_"] span');
582	        var valueEl = wrapper.querySelector(':scope > [class*="publish_metric_"]');
583	        if (labelEl && valueEl) {
584	          var label = (labelEl.textContent || '').trim();
585	          var value = (valueEl.textContent || '').trim();
586	          if (label) metrics[label] = value;
587	        }
588	      });
589	
590	      // Check this region has the expected metric names and none of the filter-out names
591	      var hasExpected = metricNames.some(function(n) { return metrics[n] !== undefined; });
592	      var hasFiltered = filterOut.some(function(n) { return metrics[n] !== undefined; });
593	      if (!hasExpected || hasFiltered) return;
594	
595	      // Walk up to find the post card container
596	      var parent = region.parentElement;
597	      for (var i = 0; i < 15 && parent; i++) {
598	        if (parent.textContent && parent.textContent.indexOf('View Post') !== -1) {
599	          if (!postParents.has(parent)) {
600	            postParents.add(parent);
601	            metricsMap.set(parent, metrics);
602	          }
603	          break;
604	        }
605	        parent = parent.parentElement;
606	      }
607	    });
608	
609	    // Find all date headers
610	    var dateHeaderPattern = /(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday),\\s+([A-Z][a-z]+\\s+\\d{1,2})/;
611	    var allDateHeaders = [];
612	    document.querySelectorAll('*').forEach(function(el) {
613	      var text = (el.textContent || '').trim();
614	      if (text.length < 50 && dateHeaderPattern.test(text)) {
615	        var match = text.match(dateHeaderPattern);
616	        if (match) {
617	          var rect = el.getBoundingClientRect();
618	          allDateHeaders.push({ date: match[0], top: rect.top + window.scrollY });
619	        }
620	      }
621	    });
622	
623	    postParents.forEach(function(container) {
624	      var containerRect = container.getBoundingClientRect();
625	      var containerTop = containerRect.top + window.scrollY;
626	
627	      // Extract post text
628	      var paragraphs = container.querySelectorAll('p, [class*="text"], [class*="content"]');
629	      var postText = '';
630	      paragraphs.forEach(function(p) {
631	        var pText = (p.textContent || '').trim();
632	        if (pText.length > 20 &&
633	            pText.indexOf('Published via') === -1 &&
634	            pText.indexOf('View Post') === -1) {
635	          // Skip if text contains any metric label names
636	          var hasMetric = metricNames.some(function(n) { return pText.indexOf(n) !== -1; });
637	          if (!hasMetric && pText.length > postText.length) {
638	            postText = pText;
639	          }
640	        }
641	      });
642	
643	      // Find closest date header above this post
644	      var dateHeader = '';
645	      var closestDateTop = -Infinity;
646	      for (var h = 0; h < allDateHeaders.length; h++) {
647	        var header = allDateHeaders[h];
648	        if (header.top < containerTop && header.top > closestDateTop) {
649	          closestDateTop = header.top;
650	          dateHeader = header.date;
651	        }
652	      }
653	
654	      // Find the time
655	      var timeStr = '';
656	      var current = container;
657	      for (var i = 0; i < 5 && current && !timeStr; i++) {
658	        var sibling = current.previousElementSibling;
659	        for (var j = 0; j < 3 && sibling && !timeStr; j++) {
660	          var sibText = sibling.textContent || '';
661	          var timeMatch = sibText.match(/\\b(\\d{1,2}:\\d{2}\\s*(AM|PM))\\b/i);
662	          if (timeMatch) {
663	            timeStr = timeMatch[1];
664	          }
665	          sibling = sibling.previousElementSibling;
666	        }
667	        current = current.parentElement;
668	      }
669	
670	      var metrics = metricsMap.get(container) || {};
671	
672	      results.push({
673	        text: postText || (container.textContent || '').substring(0, 500),
674	        dateHeader: dateHeader,
675	        time: timeStr,
676	        metrics: metrics,
677	        domOrder: containerTop
678	      });
679	    });
680	
681	    results.sort(function(a, b) { return a.domOrder - b.domOrder; });
682	    return results;
683	  })()`);
684	
685	  return postContainers;
686	}
