49	export function loadEnv(): void {
50	  const envPath = path.resolve(".env");
51	  if (!fs.existsSync(envPath)) {
52	    console.error(
53	      "Missing .env file. Create one with BUFFER_API_TOKEN=your_token",
54	    );
55	    process.exit(1);
56	  }
57	
58	  const content = fs.readFileSync(envPath, "utf-8");
59	  for (const line of content.split("\n")) {
60	    const trimmed = line.trim();
61	    if (!trimmed || trimmed.startsWith("#")) continue;
62	    const eqIndex = trimmed.indexOf("=");
63	    if (eqIndex === -1) continue;
64	    const key = trimmed.substring(0, eqIndex).trim();
65	    const value = trimmed.substring(eqIndex + 1).trim();
66	    if (!process.env[key]) {
67	      process.env[key] = value;
68	    }
69	  }
70	
71	  if (!process.env.BUFFER_API_TOKEN) {
72	    console.error("BUFFER_API_TOKEN not set in .env file.");
73	    process.exit(1);
74	  }
75	}
