86	export const CREATE_POST_MUTATION = `
87	mutation CreatePost($input: CreatePostInput!) {
88	  createPost(input: $input) {
89	    ... on PostActionSuccess {
90	      post {
91	        id
92	        text
93	        status
94	        dueAt
95	      }
96	    }
97	    ... on MutationError {
98	      message
99	    }
100	  }
101	}`;
102	
103	export async function bufferApiQuery<T = unknown>(
104	  query: string,
105	  variables?: Record<string, unknown>,
106	): Promise<GraphQLResponse<T>> {
107	  const token = process.env.BUFFER_API_TOKEN;
108	  if (!token) throw new Error("BUFFER_API_TOKEN not set");
109	
110	  const response = await fetch(BUFFER_API_URL, {
111	    method: "POST",
112	    headers: {
113	      "Content-Type": "application/json",
114	      Authorization: `Bearer ${token}`,
115	    },
116	    body: JSON.stringify({ query, variables }),
117	  });
118	
119	  if (!response.ok) {
120	    throw new Error(
121	      `Buffer API request failed (${response.status}): ${await response.text()}`,
122	    );
123	  }
124	
125	  return (await response.json()) as GraphQLResponse<T>;
126	}
