229	// ============================================================================
230	// Character Limit Validation
231	// ============================================================================
232	
233	const CHAR_LIMITS = {
234	  LinkedIn: 2000,
235	  Mastodon: 500,
236	  // Bluesky's hard limit is 300, but we leave a 10-char safety margin —
237	  // empirically posts at 296-300 chars get rejected.
238	  Bluesky: 290,
239	} as const;
240	
241	// How each network counts a URL toward its character limit.
242	//  - Mastodon collapses every URL to a fixed 23 chars (its t.co-style rule).
243	//  - Bluesky and LinkedIn count URLs at FULL length: Buffer no longer shortens
244	//    links by default (since 2025-04) and Bluesky's API counts the raw URL in
245	//    the post record, so a long agilepainrelief.com + UTM link eats its whole
246	//    length. `null` means "count the URL as written".
247	//  Future: if buff.ly shortening is turned on for a channel (queryable via the
248	//  API as channel.linkShortening.isEnabled), Bluesky's per-URL count drops to
249	//  roughly the buff.ly link length (~22). We assume full length until then.
250	const URL_COUNT_LENGTH: Record<NetworkType, number | null> = {
251	  LinkedIn: null,
252	  Mastodon: 23,
253	  Bluesky: null,
254	};
255	
256	// Regex to match URLs (http/https)
257	const URL_REGEX = /https?:\/\/[^\s]+/g;
258	
259	export interface ValidationError {
260	  network: string;
261	  partIndex: number;
262	  content: string;
263	  actualLength: number;
264	  effectiveLength: number;
265	  limit: number;
266	}
267	
268	/**
269	 * Effective character count for a network. `urlCount` is the fixed number of
270	 * characters each URL collapses to on that network, or null to count URLs at
271	 * their full length (what Bluesky and LinkedIn actually do).
272	 */
273	export function calculateEffectiveLength(
274	  text: string,
275	  urlCount: number | null,
276	): number {
277	  if (urlCount === null) return text.length;
278	  const urls = text.match(URL_REGEX) || [];
279	  let effectiveLength = text.length;
280	
281	  for (const url of urls) {
